// Compact, bundled copies of completed seasons, generated by
// scripts/snapshot.ts in GitHub Actions (where ESPN is reachable without CORS
// limits). A full season of games fits in ~100 KB instead of ~45 MB of raw
// team schedules.
import type { SeasonHighsResult } from './live';
import type { PayrollPlayer } from '../lib/brefContracts';
import type { Injury } from './types';
import type { BoxTotals } from '../lib/boxTotals';
import type { ClutchTotals } from '../lib/clutch';
import type { ShotSplits } from '../lib/shotTypes';
import type { GarbageTotals } from '../lib/garbageTime';
import type { TeamQuarters } from '../lib/quarters';
import type { NightBest } from '../lib/gameLines';
import type { TeamLineupSeason } from '../lib/lineups';
import type { DramaRow, ShotBins } from '../lib/pbpStats';
import type { AssistPairs, Conference, Game, LeaderTable, TeamRef, TeamStatTable } from './types';

/** [id, date, homeId, awayId, homeScore, awayScore, note, broadcasts] */
export type CompactGame = [string, string, string, string, number | null, number | null, string | null, string | null];

export interface SeasonSnapshot {
  year: number;
  generatedAt: string;
  teams: TeamRef[];
  standings: Conference[];
  games: Record<string, CompactGame[]>;
  /** Keyed `${seasonType}:${sort}`. */
  leaders: Record<string, LeaderTable>;
  teamStats: Record<string, TeamStatTable | null>;
  highs: Record<string, SeasonHighsResult | null>;
  /** Keyed by season type, then team id. Optional: older snapshots lack it. */
  assists?: Record<string, Record<string, AssistPairs>>;
  /** Per season type: one row per game. */
  drama?: Record<string, DramaRow[]>;
  /** Per season type. */
  shots?: Record<string, ShotBins>;
  /** ESPN athlete id → full name for everyone in a box score this season. */
  players?: Record<string, string>;
  /** False while the season is still being played. */
  complete?: boolean;
  /** Per season type, then team id: most-used lineups and on/off splits. */
  lineups?: Record<string, Record<string, TeamLineupSeason>>;
  /** Regular season ('2') only: every player's and team's summed box scores. */
  box?: Record<string, BoxTotals>;
  /** Per season type: clutch-time player and team totals. */
  clutch?: Record<string, ClutchTotals>;
  /** Per season type: shot types (with assisted makes) and quarter splits. */
  shotSplits?: Record<string, ShotSplits>;
  /** Per season type, then team id: games and summed numeric team box-score stats (e.g. "Points in Paint"). */
  teamStatSums?: Record<string, Record<string, { gp: number; sums: Record<string, number> }>>;
  /** Per season type: what players and teams did in garbage time. */
  garbage?: Record<string, GarbageTotals>;
  /** Per season type, then team id: quarter-by-quarter scoring and lead records. */
  quarters?: Record<string, Record<string, TeamQuarters>>;
  /** Regular season: the best three lines of each of the last 14 nights, newest first. */
  nightly?: { day: string; best: NightBest[] }[];
  /** Season in progress: the league injury report when the snapshot was taken. */
  injuries?: Injury[];
  /** Season in progress: every team's payroll (Basketball-Reference), by ESPN team id. */
  payroll?: Record<string, PayrollPlayer[]>;
  /** Season in progress: [season, salary] by ESPN athlete id, newest first (ESPN contracts). */
  salaryHistory?: Record<string, [number, number][]>;
}

export function compactGame(g: Game): CompactGame {
  return [g.id, g.date, g.home.team.id, g.away.team.id, g.home.score ?? null, g.away.score ?? null, g.note ?? null, g.broadcasts.join(', ') || null];
}

export function expandGame(c: CompactGame, teams: Map<string, TeamRef>): Game {
  const [id, date, homeId, awayId, hs, as, note, tv] = c;
  const final = hs != null && as != null;
  const unknown = (tid: string): TeamRef => ({ id: tid, name: tid, shortName: tid, abbr: tid });
  const side = (tid: string, homeAway: 'home' | 'away', score: number | null, other: number | null) => ({
    team: teams.get(tid) ?? unknown(tid),
    homeAway,
    score: score ?? undefined,
    winner: final ? score! > other! : undefined,
    linescores: [],
    leaders: [],
  });
  return {
    id,
    date,
    state: final ? 'post' : 'pre',
    statusDetail: final ? 'Final' : '',
    home: side(homeId, 'home', hs, as),
    away: side(awayId, 'away', as, hs),
    broadcasts: tv ? tv.split(', ') : [],
    note: note ?? undefined,
  };
}
